children.input:
{
  "project_id": "9bf955e44a904bceb5ab",
  "name": "secure_delete_account_and_revoke_sessions",
  "query": "create or replace function public.delete_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  deleting_user_id uuid := (select auth.uid());
begin
  if deleting_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;

  -- Revoke every refresh token/session before removing the Auth identity.
  -- This prevents the account from obtaining another access token.
  delete from auth.sessions
  where user_id = deleting_user_id;

  delete from auth.users
  where id = deleting_user_id;

  if not found then
    raise exception 'account not found' using errcode = 'P0002';
  end if;
end;
$$;

revoke all on function public.delete_account() from public;
grant execute on function public.delete_account() to authenticated;"
}

